#!/usr/bin/env bash
# Écrit la bible de style et les prompts de chaque image de Kevspire.
mkdir -p "$(dirname "$0")/prompts" && cd "$(dirname "$0")/prompts"
T="Fond avec une VRAIE TRANSPARENCE (canal alpha), aucun décor, aucun sol, aucune ombre portée au sol, aucun texte."
S="Format carré. L'élément SEUL, entièrement visible avec une petite marge, centré. $T"

cat > _ADN.txt <<EOF
PROJET : « Kevspire », jeu mobile ORIGINAL de tower defense vertical. Dans l'Archipel des Brises, des îles flottent au-dessus d'une mer de nuages. Les Gardiens des lanternes bâtissent la Flèche, une tour vivante qui grandit étage par étage pour protéger, à son sommet, le Cœur d'Aube (un grand cristal de lumière). La nuit, les Brumâmes, créatures d'encre et de brume aux yeux luisants, montent à l'assaut de la tour. Œuvre ORIGINALE : ne reprends aucun personnage, logo, style signature ni élément d'un jeu, film ou dessin animé existant.

STYLE VERROUILLÉ (identique pour toutes les images du jeu) : illustration numérique peinte de jeu mobile premium, formes très lisibles et silhouettes fortes, contours nets légèrement sombres, aplats peints avec dégradés doux et fine texture de gouache, proportions stylisées et chaleureuses (ni chibi ni réaliste), lumière de crépuscule. Palette : bleu nuit profond (#1B2340), violet prune (#3B2A5C), corail (#FF7A59), or chaud des lanternes (#FFC857), crème pierre (#F3E3C3), avec un accent magique cyan luciole (#6FF3E0). Les Gardiens et la tour sont chauds (bois miel, laiton, pierre crème, toiles corail) ; les Brumâmes sont froids (encre indigo, violet, yeux cyan ou magenta). Aucun texte, aucune lettre, aucun logo, aucune signature, aucun filigrane.
EOF

p() { printf '%s\n' "$2" > "$1.txt"; }
p fond_titre "ILLUSTRATION D'ÉCRAN TITRE, format VERTICAL (portrait 9:16), très épique et accueillante. Au centre, une haute tour élancée et un peu tordue, faite d'étages empilés de pierre crème, de bois miel et de laiton, avec des balcons, des lanternes or, des voiles corail et de petites tourelles, plantée sur une île flottante herbeuse. À son sommet brille un grand cristal cyan-or, le Cœur d'Aube, qui projette un halo. Autour, ciel de crépuscule corail et violet, mer de nuages en bas, autres îlots flottants lointains, lucioles cyan. Dans les nuages du bas et sur les côtés, des silhouettes de créatures d'encre indigo aux yeux luisants qui commencent à grimper. Laisser le QUART SUPÉRIEUR relativement calme (ciel) pour y poser le titre du jeu plus tard. Aucun texte."
p ciel_crepuscule "DÉCOR DE FOND (ciel seul) format VERTICAL (portrait 9:16) pour un jeu vertical. Ciel de crépuscule : haut bleu nuit qui se dégrade vers violet puis corail et or près du bas. Quelques gros nuages cotonneux éclairés en corail, deux ou trois petits îlots flottants très lointains avec de minuscules lanternes, premières étoiles en haut. Le CENTRE de l'image (bande verticale) reste dégagé et calme, sans élément fort, car une tour sera dessinée par-dessus. Aucune tour, aucun personnage, aucune créature."
p ciel_nuit "DÉCOR DE FOND (ciel seul) format VERTICAL (portrait 9:16) pour un jeu vertical. Pleine nuit au-dessus d'une mer de nuages : grande lune pâle en haut à gauche, ciel bleu nuit profond et violet, voie lactée douce, nuages argentés éclairés par la lune, îlots flottants lointains en silhouette avec quelques lumières or. Le CENTRE de l'image (bande verticale) reste dégagé et calme, car une tour sera dessinée par-dessus. Aucune tour, aucun personnage, aucune créature."
p ciel_orage "DÉCOR DE FOND (ciel seul) format VERTICAL (portrait 9:16) pour un jeu vertical. Ciel d'orage magique juste avant l'aube : lourds nuages violet prune et indigo, rubans d'aurore cyan et magenta qui ondulent, éclairs lointains, une lueur corail à l'horizon tout en bas. Ambiance dramatique de dernier niveau. Le CENTRE de l'image (bande verticale) reste dégagé, car une tour sera dessinée par-dessus. Aucune tour, aucun personnage, aucune créature."
p ile_base "ÉLÉMENT DE DÉCOR : une île flottante vue de face, de profil (vue latérale), format PAYSAGE large (environ 3 pour 1). Dessus plat et herbeux avec petites fleurs, quelques rochers, deux petites lanternes plantées sur les bords, un chemin de pierre au centre. Dessous en pointe de roche crème et brune, avec racines pendantes et petits cristaux cyan, qui s'effile vers le bas. Le dessus herbeux doit être PLAT et HORIZONTAL au centre (une tour y sera posée). L'île SEULE, entière, centrée. $T"
ETAGE="Le bord SUPÉRIEUR et le bord INFÉRIEUR sont parfaitement HORIZONTAUX et droits, de même largeur, pour pouvoir empiler les étages. Pas de balcon, pas de toit. L'étage occupe toute la largeur moins une petite marge. $T"
p etage_a "ÉLÉMENT DE DÉCOR : UN SEUL étage de tour vu parfaitement DE FACE (vue orthographique, sans perspective), format carré. Un bloc cylindrique de pierre crème à joints visibles, cerclé en haut et en bas d'une poutre de bois miel bordée de laiton. Au centre, une fenêtre ronde éclairée de l'intérieur (lumière or chaude). $ETAGE"
p etage_b "ÉLÉMENT DE DÉCOR : UN SEUL étage de tour vu parfaitement DE FACE (vue orthographique, sans perspective), format carré. Un bloc cylindrique de bois miel et de colombages, avec une petite porte-fenêtre en arc éclairée or, des lierres et une petite lanterne accrochée, cerclé en haut et en bas d'une bande de pierre crème. $ETAGE"
p etage_c "ÉLÉMENT DE DÉCOR : UN SEUL étage de tour vu parfaitement DE FACE (vue orthographique, sans perspective), format carré. Un bloc cylindrique d'atelier : pierre crème et plaques de laiton rivetées, un grand engrenage décoratif en laiton, deux petits hublots éclairés cyan, des tuyaux. Cerclé en haut et en bas d'une poutre de bois miel. $ETAGE"
p sommet "ÉLÉMENT DE DÉCOR : le SOMMET d'une tour vu parfaitement DE FACE (vue orthographique), format carré. Une couronne ouverte en laiton et bois miel, comme un berceau à arceaux, avec des fanions corail et quatre petites lanternes or, posée sur un court tronçon de tour en pierre crème dont le bord INFÉRIEUR est parfaitement HORIZONTAL (pour se poser sur les étages). Le centre de la couronne est VIDE (un cristal y sera ajouté séparément). $S"
p coeur "OBJET : le « Cœur d'Aube », grand cristal magique en forme de goutte facettée allongée, pointe vers le haut, cœur lumineux cyan qui vire à l'or au centre, reflets blancs, petites étincelles autour, halo doux. Majestueux et précieux. $S"
p baliste "TOURELLE DE DÉFENSE « Baliste » vue de TROIS QUARTS FACE, légèrement de dessus : une arbalète géante en bois miel et laiton montée sur un petit socle rond rotatif, arc tendu, carreau à pointe or chargé, petit fanion corail. Compacte, lisible en petit sur mobile. Arme pointée vers le HAUT et la droite. $S"
p phare "TOURELLE DE DÉFENSE « Phare » vue de TROIS QUARTS FACE : une grosse lanterne de laiton à lentille ronde, sur un petit socle de pierre crème, d'où sort un rayon de lumière or et cyan concentré. Verre facetté, ailettes de laiton, lueur chaude. Compacte, lisible en petit. $S"
p mortier "TOURELLE DE DÉFENSE « Mortier à braises » vue de TROIS QUARTS FACE : un petit mortier trapu en fonte sombre cerclé de laiton, bouche large tournée vers le haut, braises orange et corail qui rougeoient à l'intérieur, petite fumée, sur un socle de bois miel. Compact, lisible en petit. $S"
p cloche "TOURELLE DE DÉFENSE « Cloche de givre » vue de TROIS QUARTS FACE : une cloche de bronze bleuté suspendue dans un petit portique de bois miel, givrée sur les bords, petits cristaux de glace cyan qui flottent autour, onde de froid visible. Compacte, lisible en petit. $S"
p bobine "TOURELLE DE DÉFENSE « Bobine d'orage » vue de TROIS QUARTS FACE : une bobine de cuivre en spirale surmontée d'une sphère de verre où crépite un petit éclair cyan et violet, sur un socle de laiton à pieds griffus, arcs électriques. Compacte, lisible en petit. $S"
p grignot "CRÉATURE ENNEMIE « Grignot » : petite Brumâme d'encre indigo, ronde et trapue comme une goutte, quatre petites pattes griffues pour grimper, deux grands yeux cyan luisants, petites cornes molles, bouche dentue mais plus espiègle que gore, bord du corps qui s'effiloche en fumée violette. Vue de PROFIL, tournée vers la DROITE, en train de courir. $S"
p papillombre "CRÉATURE ENNEMIE VOLANTE « Papillombre » : papillon de nuit d'encre et de brume, ailes violet prune déchiquetées aux motifs d'yeux magenta, corps indigo velu, deux yeux cyan, antennes plumeuses, traînée de poussière sombre. Vue de FACE, ailes déployées. $S"
p carapace "CRÉATURE ENNEMIE « Carapace » : grosse Brumâme blindée lente, comme un scarabée-tatou d'encre indigo couvert de plaques d'ardoise grise fissurées, petits yeux cyan sous un front de pierre, six pattes épaisses, brume violette qui s'échappe des jointures. Vue de PROFIL, tournée vers la DROITE. $S"
p fouisseur "CRÉATURE ENNEMIE « Fouisseur » : Brumâme taupe-ver d'encre indigo au museau de foreuse en pierre noire spiralée, grandes griffes avant pelles, yeux magenta minuscules, corps segmenté qui sort d'un nuage de poussière violette. Vue de PROFIL tournée vers la DROITE. $S"
p moucheron "CRÉATURE ENNEMIE VOLANTE « Moucheron d'essaim » : minuscule Brumâme volante, une petite boule de fumée indigo avec un seul gros œil magenta, deux ailes de libellule translucides violettes, petite queue de fumée. Mignonne mais menaçante. Vue de FACE. $S"
p planeur "CRÉATURE ENNEMIE VOLANTE « Planeur spectral » : raie volante faite de brume indigo et violette semi-transparente, grande envergure, motifs lumineux cyan qui ondulent sur le dos, longue queue en fouet, deux yeux magenta. Vue de DESSUS-FACE, en vol plané. $S"
p mere_brume "BOSS ENNEMI « la Mère-Brume » : colossale Brumâme, silhouette de pieuvre-araignée d'encre indigo, couronne de cornes d'ardoise, six yeux cyan et magenta, longs bras griffus qui s'agrippent, ventre où tourbillonnent de petites Brumâmes, nuée violette qui s'échappe de partout. Imposante, menaçante mais pas gore. Vue de FACE. $S"
p gardienne "PORTRAIT DE DIALOGUE (buste, de la taille à la tête) de « Lumi », jeune Gardienne des lanternes de 16 ans, guide du joueur. Peau brun doré, cheveux bouclés noirs attachés en gros chignon d'où sortent des mèches, petites taches de rousseur claires, grands yeux noisette pétillants, sourire confiant. Manteau court de toile corail à col de laiton, écharpe crème, lunettes d'atelier en laiton sur le front, une petite lanterne or qui pend à sa ceinture, une luciole cyan posée sur son épaule. Regarde vers la DROITE. Format carré, cadré buste. $T"
p maquette_hud "MAQUETTE D'INTERFACE de jeu mobile, écran de téléphone VERTICAL (9:16), pour inspirer un designer : on voit en vue latérale une haute tour à étages au centre, avec des tourelles sur des balcons de chaque côté, des créatures d'encre qui grimpent les murs et volent autour. Interface élégante type jeu premium : en haut une barre fine avec pièces d'or, cœurs de vie et numéro de vague dans des cartouches arrondis en laiton et verre sombre ; en bas un bandeau avec deux gros boutons ronds de pouvoirs lumineux et un bouton de vitesse ; un menu radial circulaire ouvert autour d'un emplacement de balcon proposant 5 icônes de tourelles. Typographie et pictogrammes stylisés, pas de texte lisible (juste des formes de chiffres). Rendu très soigné, cohérent avec la DA."
echo "prompts écrits : $(ls | wc -l)"
